void af_model_quantize(const float features[AF_MODEL_FEATURE_COUNT], int8_t output[AF_MODEL_FEATURE_COUNT])
{
    for (size_t i = 0; i < AF_MODEL_FEATURE_COUNT; ++i) {
        long value = lroundf(features[i] / feature_scales[i]) + feature_zero_points[i];
        if (value < -128) value = -128;
        if (value > 127) value = 127;
        output[i] = (int8_t)value;
    }
}

af_model_result_t af_model_predict_int8(const int8_t features[AF_MODEL_FEATURE_COUNT])
{
    uint32_t score = 0;
    uint16_t comparisons = 0;
    for (size_t tree = 0; tree < AF_MODEL_TREE_COUNT; ++tree) {
        int16_t index = (int16_t)tree_roots[tree];
        while (!nodes[index].is_leaf) {
            const af_node_t *node = &nodes[index];
            index = features[node->feature] <= node->threshold ? node->left : node->right;
            ++comparisons;
        }
        score += nodes[index].probability;
    }
    af_model_result_t result = {(uint16_t)score, comparisons};
    return result;
}

int af_model_predict(const float features[AF_MODEL_FEATURE_COUNT])
{
    int8_t quantized[AF_MODEL_FEATURE_COUNT];
    af_model_quantize(features, quantized);
    return af_model_predict_int8(quantized).score >= AF_MODEL_SCORE_THRESHOLD;
}

size_t af_model_flash_bytes(void)
{
    return sizeof(nodes) + sizeof(tree_roots) + sizeof(feature_scales) + sizeof(feature_zero_points);
}
size_t af_model_working_ram_bytes(void)
{
    return AF_MODEL_FEATURE_COUNT * sizeof(int8_t) + sizeof(af_model_result_t) + sizeof(uint32_t);
}
